/** Compact Host instructions generated by `stetra init`. */

import { hostAdapterDefinition, type HostAdapter } from './definition.ts';

export type { HostAdapter } from './definition.ts';

export const HOST_WORKFLOW_REFERENCES = ['recovery'] as const;
export type HostWorkflowReference = typeof HOST_WORKFLOW_REFERENCES[number];

export function renderHostSkill(adapter: HostAdapter): string {
  const host = hostAdapterDefinition(adapter).displayName;
  return `---
name: stetra
description: Deliver an inspectable coding change while preserving developer understanding and adoption authority.
---

# Stetra

Use Stetra for production coding changes. ${host} investigates, implements,
tests, and explains the change. The developer owns intent, long-lived choices,
exceptions, and adoption. Stetra records workflow facts and keeps those
authorities separate.

## Follow the projected action

1. At the start of a task, run the exact command projected by the SessionStart
   hook. If no command is projected, use the portable Hook-independent entry
   once:
   **stetra input reserve . --kind prepare --json**. Edit only the open Draft
   fields and run its exact **submit.argv**. Never invoke **stetra host begin**
   without the projected adapter and one-time binding token, and never
   reconstruct either value.
2. Follow **hostAction.kind** and its exact **command.argv**. Do not reconstruct a
   command from prose.
3. When **hostAction.inputBinding** exists, run its **reserve.argv**, edit only the
   open fields in the returned Draft, consult the task-specific Guide when
   needed, and run the projected command.
4. Use **stetra change explain** only for detail required by the current action.
5. Before a final response, run the exact **hostAction.finalResponseGuard.argv**
   projected for the task. Continue the workflow if it reports unfinished work
   or stale facts. Never invoke **stetra host hook** manually; provider Hooks are
   an automatic continuity backstop.

Treat frozen commands executed by Stetra as Runtime observations. Treat direct
tool use, repository interpretation, diagnoses, and recommendations as Agent
judgment. A passing command is evidence, not proof of product meaning, and
**handoff-ready** never means adopted.

For the final handoff, lead with **developerDecisionBrief.primary**. Preserve
the separate delivery, evidence, recommendation, and adoption states. Then give
a compact actual-system explanation: the changed behavior, the core mechanism,
and any material invariant or failure path. State the exact baseline-to-current
Check changes, preserve every blocker and required review decision, and make the
remaining Human choice explicit. Do not replace this with a changed-file list
or a generic completion summary. Say that adoption is pending and ask the
developer to accept, request correction, reject, or defer. Do not submit a
decision until a new developer message provides it. Present that question as
plain text in the final response and then stop. Do not invoke an interactive
input tool for the adoption decision; only the developer's next message can
authorize it.

Never invent Runtime facts, hide a failed check, infer assurance from repository
shape, or claim that this thin adapter created an independent Agent context.
`;
}

export function renderHostWorkflowReference(
  _adapter: HostAdapter,
  workflow: HostWorkflowReference,
): string {
  if (workflow !== 'recovery') throw new Error(`Unsupported workflow reference: ${workflow}`);
  return RECOVERY_REFERENCE;
}

export function renderHostPointerBlock(
  adapter: HostAdapter,
  markers: { start: string; end: string },
): string {
  const skillPath = `${hostAdapterDefinition(adapter).skillRoot}/SKILL.md`;
  return `${markers.start}
For production coding changes, follow [the generated Stetra skill](${skillPath}).
${markers.end}`;
}

export function delegationPrepareDraft() {
  return {
    developerEvents: [{ key: 'request', content: '', provider: 'host' }],
    task: {
      desiredOutcome: '',
      constraints: [],
      nonGoals: [],
      focus: [],
      repositoryEvidenceKeys: [],
    },
    assurance: {
      kind: 'routine',
      rationale: '',
    },
    verification: {
      mode: 'checks',
      checks: [],
    },
  } as const;
}

export function delegationPrepareGuide() {
  return {
    inputKind: 'prepare',
    authority: {
      developerEvents: 'exact-human-event',
      taskAssuranceAndVerification: 'agent-judgment',
    },
    requiredChoices: {
      assurance: [
        'Use routine with a concrete rationale and basis only when no material adoption condition is needed.',
        'Use conditioned with one or more falsifiable Conditions when a bounded claim can change adoption.',
      ],
      verification: [
        'Use verification.mode checks with exact repository-valid argv definitions.',
        'Or use verification.mode no-command with a concrete rationale.',
      ],
    },
    exactConstraints: [
      'The exact Prepare transport identity is bound by submit.argv and is not editable in this Draft.',
      'Every developerEvents entry is an exact Human Event; preserve its wording and use a stable readable key.',
      'Use executionBudgetOverride only when the task requires bounds different from the Runtime defaults.',
      'Execution inputs name only required ignored or generated files or trees; do not use the repository root as an input path.',
    ],
    schema: {
      included: false,
      command: { argv: ['stetra', 'input', 'schema', '.', '--kind', 'prepare', '--json'] },
    },
  };
}

const RECOVERY_REFERENCE = `# Recover a Stetra task

Follow the current \`hostAction.kind\` and exact \`command.argv\`.

- \`retry-timed-out-check\`: run the larger-budget retry without changing the
  worktree. Earlier attempts remain part of the evidence.
- \`diagnose-collected-evidence\`: complete the projected diagnosis for every
  listed concern. Diagnose; do not assume repair.
- \`revise-verification\`: revise the projected verifier definition without
  overwriting its history or claiming an unobserved baseline.
- \`recollect-stale-facts\`: collect again before authoring a handoff.
- \`resolve-evidence-decision\`: preserve the evidence gap and record the exact
  developer resolution requested by the Draft.
- \`correct-protocol-input\`, \`configure-verification\`, or
  \`resolve-human-choice\`: correct only the named missing input or authority.

For an input-bearing action, run \`inputBinding.reserve.argv\`, edit the owned
Draft at \`inputBinding.draftPath\`, use \`inputBinding.guidePath\` only when
needed, and run the projected command. A validation error reissues that Draft;
repair it instead of creating another task.

Use \`stetra change explain . --task <task-id> --section <name> --json\` for
canonical detail. Failed or unavailable checks, changed verifier surfaces,
unrepresentable changes, residual unknowns, and missing independent evidence
remain visible. They are not scores and do not automatically decide adoption.
`;
